source(file.path(dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value=TRUE)[1]), mustWork=FALSE)), "backend_common.R"))
opts<-parse_cli_args();require_args(opts,c("vectors","outdir"));v<-readr::read_tsv(opts$vectors,show_col_types=FALSE);cols<-grep("^v",names(v),value=TRUE);M<-as.matrix(v[,cols]); mu<-colMeans(M); stab<-vapply(seq_len(ncol(M)),function(j)cosine_similarity(mu,colMeans(M[,-j,drop=FALSE])),numeric(1));write_tsv_safe(tibble(feature=sub("^v","",cols),mean_direction=mu,leave_feature_out_direction_cosine=stab,interpretation="descriptive directional contributors, not biomarkers or causal features"),file.path(ensure_outdir(opts$outdir),"directional_feature_stability.tsv"))
